public int[] shortestReach(int n, int[][] edges, int s) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    int[] dist = new int[n + 1];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[s] = 0;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    heap.offer(new int[]{0, s});
    while (!heap.isEmpty()) {
        int[] top = heap.poll();
        int d = top[0], u = top[1];
        if (d > dist[u]) continue;
        for (int v : adj.get(u)) {
            if (dist[u] + 6 < dist[v]) {
                dist[v] = dist[u] + 6;
                heap.offer(new int[]{dist[v], v});
            }
        }
    }
    int[] out = new int[n - 1];
    int idx = 0;
    for (int i = 1; i <= n; i++) {
        if (i == s) continue;
        out[idx++] = dist[i] == Integer.MAX_VALUE ? -1 : dist[i];
    }
    return out;
}

