import heapq

def shortest_reach(self, n: int, edges: list[list[int]], s: int) -> list[int]:
    adj: list[list[int]] = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[s] = 0
    heap = [(0, s)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v in adj[u]:
            if dist[u] + 6 < dist[v]:
                dist[v] = dist[u] + 6
                heapq.heappush(heap, (dist[v], v))
    return [(-1 if dist[i] == INF else dist[i]) for i in range(1, n + 1) if i != s]

