public int[] shortestReach(int n, int[][] edges, int s) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    int[] dist = new int[n + 1];
    Arrays.fill(dist, -1);
    dist[s] = 0;
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(s);
    while (!queue.isEmpty()) {            // iterative BFS, no stack overflow
        int u = queue.poll();
        for (int v : adj.get(u)) {
            if (dist[v] == -1) {         // first reach = shortest reach
                dist[v] = dist[u] + 6;   // uniform edge weight
                queue.offer(v);
            }
        }
    }
    int[] out = new int[n - 1];
    int idx = 0;
    for (int i = 1; i <= n; i++) {
        if (i == s) continue;
        out[idx++] = dist[i];            // already -1 if unreached
    }
    return out;
}

